"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[85669],{92468:e=>{e.exports=JSON.parse('{"blogPosts":[{"id":"/220","metadata":{"permalink":"/de/release/220","source":"@site/i18n/de/docusaurus-plugin-content-blog/220.mdx","title":"v2.2.0","description":"Neue KI-Ressourcen wurden hinzugef\xfcgt.","date":"2026-01-01T00:00:00.000Z","formattedDate":"1. Januar 2026","tags":[],"readingTime":0.51,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v2.2.0","last_update":"2026-01-01T00:00:00.000Z","date":"2026-01-01T00:00:00.000Z"},"nextItem":{"title":"v2.1.0","permalink":"/de/release/210"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Neue KI-Ressourcen wurden hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Neue KI-Ressourcen auf Basis von AWS und Azure wurden hinzugef\xfcgt.\\n\\n    - AWS KI-Ressourcen\\n\\n        - Bedrock Agent\\n        - Bedrock Knowledge Base\\n        - Bedrock Action Group\\n        - Bedrock Guardrail\\n\\n    - Azure KI-Ressourcen\\n\\n        - Content Safety\\n        - AI Service\\n        - Search Service\\n\\n    - Benutzer k\xf6nnen nun KI-bezogene Ressourcen, die von f\xfchrenden Cloud-Services bereitgestellt werden, intuitiver entwerfen und verwalten.\\n\\n2. Eine Funktion zum Anzeigen/Ausblenden von Konfigurationsfehlern wurde hinzugef\xfcgt.\\n    - Auch wenn in Ressourcen ungel\xf6ste Fehler vorhanden sind, k\xf6nnen Fehleranzeigen optional ein- oder ausgeblendet werden.\\n\\n</div>\\n<br/>"},{"id":"/210","metadata":{"permalink":"/de/release/210","source":"@site/i18n/de/docusaurus-plugin-content-blog/210.mdx","title":"v2.1.0","description":"Eine neue Social-Login-Funktion auf Basis von Microsoft- und Google-OAuth wurde hinzugef\xfcgt.","date":"2025-11-18T00:00:00.000Z","formattedDate":"18. November 2025","tags":[],"readingTime":0.325,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v2.1.0","last_update":"2025-11-18T00:00:00.000Z","date":"2025-11-18T00:00:00.000Z"},"prevItem":{"title":"v2.2.0","permalink":"/de/release/220"},"nextItem":{"title":"v2.0.0","permalink":"/de/release/200"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Eine neue Social-Login-Funktion auf Basis von Microsoft- und Google-OAuth wurde hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Der OAuth-basierte Social Login mit Microsoft- und Google-Konten wird neu unterst\xfctzt.\\n\\n    - Dadurch k\xf6nnen sich Benutzer ohne separate Registrierung schnell mit ihren Microsoft- oder Google-Konten anmelden.\\n    - Die Authentifizierung auf Basis von OAuth 2.0 wird unterst\xfctzt.\\n\\n</div>\\n<br/>"},{"id":"/200","metadata":{"permalink":"/de/release/200","source":"@site/i18n/de/docusaurus-plugin-content-blog/200.mdx","title":"v2.0.0","description":"Die AI-Builder-Funktion wurde hinzugef\xfcgt.","date":"2025-10-10T00:00:00.000Z","formattedDate":"10. Oktober 2025","tags":[],"readingTime":0.42,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v2.0.0","last_update":"2025-10-10T00:00:00.000Z","date":"2025-10-10T00:00:00.000Z"},"prevItem":{"title":"v2.1.0","permalink":"/de/release/210"},"nextItem":{"title":"v1.9.0","permalink":"/de/release/190"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Die AI-Builder-Funktion wurde hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Die AI-Builder-Funktion wurde hinzugef\xfcgt.\\n\\n    - Anstelle der bisherigen Infrastrukturplanung durch Drag & Drop von Ressourcen-Icons wurde eine AI-Builder-Funktion erg\xe4nzt, mit der die Infrastruktur durch einfache Texteingaben entworfen werden kann.\\n    - Der AI Builder analysiert die eingegebenen Anforderungen, schl\xe4gt optimierte Cloud-Ressourcen vor und erstellt automatisch ein Architekturdiagramm.\\n    - Die mit dem AI Builder generierte Architektur kann vom Benutzer direkt angepasst und erweitert werden.\\n\\n</div>\\n<br/>"},{"id":"/190","metadata":{"permalink":"/de/release/190","source":"@site/i18n/de/docusaurus-plugin-content-blog/190.mdx","title":"v1.9.0","description":"CloudStudio und CS Checker wurden integriert.","date":"2025-08-19T00:00:00.000Z","formattedDate":"19. August 2025","tags":[],"readingTime":0.4,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.9.0","last_update":"2025-8-19","date":"2025-8-19"},"prevItem":{"title":"v2.0.0","permalink":"/de/release/200"},"nextItem":{"title":"v1.8.0","permalink":"/de/release/180"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### CloudStudio und CS Checker wurden integriert.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Die Funktionen von CS Checker k\xf6nnen nun in CloudStudio genutzt werden.\\n\\n    - CS Checker ist ein integrierter Cloud-Sicherheitsmanagement-Service,\\n      der Funktionen wie ein Cloud-Infrastruktur-Asset-Register,\\n      Asset-Vergleiche und Asset-Visualisierung bereitstellt und im Bereich der Konsolenpr\xfcfung unter anderem Schwachstellenanalysen, Monitoring sowie die Erstellung von Berichten unterst\xfctzt.\\n    - Ab sofort k\xf6nnen die Funktionen von CS Checker gemeinsam mit CloudStudio genutzt werden.\\n\\n</div>\\n<br/>"},{"id":"/180","metadata":{"permalink":"/de/release/180","source":"@site/i18n/de/docusaurus-plugin-content-blog/180.mdx","title":"v1.8.0","description":"Das Pro-Abonnement wird zeitlich begrenzt kostenlos angeboten.","date":"2025-08-01T00:00:00.000Z","formattedDate":"1. August 2025","tags":[],"readingTime":0.575,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.8.0","last_update":"2025-8-1","date":"2025-8-1"},"prevItem":{"title":"v1.9.0","permalink":"/de/release/190"},"nextItem":{"title":"v1.7.0","permalink":"/de/release/170"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Das Pro-Abonnement wird zeitlich begrenzt kostenlos angeboten.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"changed\\">\\n    Update\\n</div>\\n\\n1. Das Pro-Abonnement wird zeitlich begrenzt kostenlos angeboten.\\n    - Im Pro-Abonnement stehen alle Funktionen zur Verf\xfcgung.\\n        - Canvas zeichnen\\n        - Kostenberechnung\\n        - Schwachstellenpr\xfcfung\\n        - Infrastruktur importieren\\n        - Infrastruktur bereitstellen (Terraform plan, apply)\\n        - KI-gest\xfctzte Infrastruktur-\xdcberpr\xfcfung\\n        - C2C-Canvas-Konvertierung\\n\\n</div>\\n<br/>\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Eine KI-Anleitung f\xfcr Terraform-Fehler wurde hinzugef\xfcgt.\\n\\n    - Bei der Nutzung der Funktionen Vorabpr\xfcfung (plan) und Bereitstellung (apply) analysiert die KI auftretende Terraform-Fehler und schl\xe4gt entsprechende L\xf6sungsans\xe4tze vor.\\n\\n2. Kubernetes-Ressourceninformationen k\xf6nnen abgerufen werden.\\n    - Get-, Logs- und Event-Informationen zu bereitgestellten Kubernetes-Ressourcen k\xf6nnen eingesehen werden.\\n\\n</div>\\n<br/>"},{"id":"/170","metadata":{"permalink":"/de/release/170","source":"@site/i18n/de/docusaurus-plugin-content-blog/170.mdx","title":"v1.7.0","description":"Die Kubernetes-Importfunktion wurde hinzugef\xfcgt.","date":"2025-06-16T00:00:00.000Z","formattedDate":"16. Juni 2025","tags":[],"readingTime":0.365,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.7.0","last_update":"2025-6-16","date":"2025-6-16"},"prevItem":{"title":"v1.8.0","permalink":"/de/release/180"},"nextItem":{"title":"v1.6.1","permalink":"/de/release/161"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Die Kubernetes-Importfunktion wurde hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Die Kubernetes-Importfunktion wurde hinzugef\xfcgt.\\n    - In dem Kubernetes Provider wurde eine Importfunktion erg\xe4nzt, mit der bereits bereitgestellte Kubernetes-Ressourcen als Diagramm visualisiert werden k\xf6nnen.\\n        - Zielplattformen: AKS (Microsoft Azure), EKS (AWS), NKS (Naver Cloud)\\n    - Importierte Kubernetes-Ressourcen werden in Terraform-Code umgewandelt.\\n    - \xdcber die Funktion \u201etfstate erstellen\u201c kann eine Terraform-State-Datei generiert werden.\\n\\n</div>\\n<br/>"},{"id":"/161","metadata":{"permalink":"/de/release/161","source":"@site/i18n/de/docusaurus-plugin-content-blog/161.mdx","title":"v1.6.1","description":"Die Bereitstellung kann durch die Trennung von Terraform Workspaces durchgef\xfchrt werden.","date":"2025-05-23T00:00:00.000Z","formattedDate":"23. Mai 2025","tags":[],"readingTime":0.36,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.6.1","last_update":"2025-5-23","date":"2025-5-23"},"prevItem":{"title":"v1.7.0","permalink":"/de/release/170"},"nextItem":{"title":"v1.6.0","permalink":"/de/release/160"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Die Bereitstellung kann durch die Trennung von Terraform Workspaces durchgef\xfchrt werden.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Durch die Nutzung der Workspace-Funktion von Terraform wird die getrennte Bereitstellung der Infrastruktur nach Umgebungen unterst\xfctzt.\\n    - Terraform Workspaces k\xf6nnen erstellt und gel\xf6scht werden.\\n    - Durch die getrennte Verwaltung der Statusdateien (State) pro Workspace k\xf6nnen Entwicklungs-, Staging- und Produktionsumgebungen unabh\xe4ngig voneinander betrieben werden.\\n\\n</div>\\n<br/>"},{"id":"/160","metadata":{"permalink":"/de/release/160","source":"@site/i18n/de/docusaurus-plugin-content-blog/160.mdx","title":"v1.6.0","description":"Terraform Enterprise-Integration wird unterst\xfctzt.","date":"2025-02-07T00:00:00.000Z","formattedDate":"7. Februar 2025","tags":[],"readingTime":0.255,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.6.0","last_update":"2025-2-7","date":"2025-2-7"},"prevItem":{"title":"v1.6.1","permalink":"/de/release/161"},"nextItem":{"title":"v1.5.1","permalink":"/de/release/151"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Terraform Enterprise-Integration wird unterst\xfctzt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Unterst\xfctzung der Terraform Enterprise-Version\\n\\n    - Die Versionen Terraform Cloud und Terraform Enterprise werden f\xfcr das Bereitstellungsmanagement unterst\xfctzt.\\n    - F\xfcr die Integration von Terraform Enterprise wird ein gehosteter Endpoint ben\xf6tigt.\\n\\n</div>\\n<br/>"},{"id":"/151","metadata":{"permalink":"/de/release/151","source":"@site/i18n/de/docusaurus-plugin-content-blog/151.mdx","title":"v1.5.1","description":"Benachrichtigungsdienst f\xfcr Bereitstellung und Laden wurde hinzugef\xfcgt.","date":"2025-01-23T00:00:00.000Z","formattedDate":"23. Januar 2025","tags":[],"readingTime":0.395,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.5.1","last_update":"2025-1-23","date":"2025-1-23"},"prevItem":{"title":"v1.6.0","permalink":"/de/release/160"},"nextItem":{"title":"v1.5.0","permalink":"/de/release/150"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Benachrichtigungsdienst f\xfcr Bereitstellung und Laden wurde hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Benachrichtigungsdienst f\xfcr Bereitstellung und Laden wurde hinzugef\xfcgt.\\n\\n    - Eine Benachrichtigungs-E-Mail wird nach Abschluss des Bereitstellungs- und Ladeprozesses gesendet.\\n    - Um den Benachrichtigungsdienst zu nutzen, ist die Integration des Terraform-Plugins erforderlich.\\n\\n</div>\\n<br/>\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"changed\\">\\n    Update\\n</div>\\n\\n2. AI Infrastruktur-Review-Berichtsformat hinzugef\xfcgt\\n\\n    - Beim Herunterladen des AI Infrastruktur-Review-Berichts wird zus\xe4tzlich das Markdown-Format angeboten.\\n\\n</div>"},{"id":"/150","metadata":{"permalink":"/de/release/150","source":"@site/i18n/de/docusaurus-plugin-content-blog/150.mdx","title":"v1.5.0","description":"AI-Dienste wurden hinzugef\xfcgt.","date":"2024-12-01T00:00:00.000Z","formattedDate":"1. Dezember 2024","tags":[],"readingTime":0.39,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.5.0","last_update":"2024-12-01T00:00:00.000Z","date":"2024-12-01T00:00:00.000Z"},"prevItem":{"title":"v1.5.1","permalink":"/de/release/151"},"nextItem":{"title":"v1.4.1","permalink":"/de/release/141"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### AI-Dienste wurden hinzugef\xfcgt.\\n\\n[**AI Docs Direktlink**](https://docs.cstudio.app/de/docs/ai/text-to-infra)\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. AI-Dienste wurden hinzugef\xfcgt.\\n\\n    - Text to Infrastructure: Bei der Erstellung eines Projekts kann durch generative KI Infrastruktur aus Text erstellt werden.\\n    - AI Infrastruktur-\xdcberpr\xfcfung: Der Status und Verbesserungsvorschl\xe4ge der konfigurierten Infrastruktur k\xf6nnen leicht erkannt werden.\\n    - AI-Chatbot: Sie k\xf6nnen den AI-Chatbot nutzen, um Fragen zur Nutzung von CloudStudio und zur Verbesserung der Infrastruktur zu stellen.\\n\\n</div>"},{"id":"/141","metadata":{"permalink":"/de/release/141","source":"@site/i18n/de/docusaurus-plugin-content-blog/141.mdx","title":"v1.4.1","description":"VCS-Integration (Github, Gitlab) wurde aktualisiert.","date":"2024-09-23T00:00:00.000Z","formattedDate":"23. September 2024","tags":[],"readingTime":0.19,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.4.1","last_update":"2024-09-23T00:00:00.000Z","date":"2024-09-23T00:00:00.000Z"},"prevItem":{"title":"v1.5.0","permalink":"/de/release/150"},"nextItem":{"title":"v1.4.0","permalink":"/de/release/140"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### VCS-Integration (Github, Gitlab) wurde aktualisiert.\\n\\n[**Direktlink zur VCS-Integration**](https://docs.cstudio.app/de/docs/plugin/vcs/add-github)\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"changed\\">\\n    Update\\n</div>\\n\\n1. VCS Integration\\n    - Die Funktionen zur Integration von Github und Gitlab wurden aktualisiert.\\n\\n</div>"},{"id":"/140","metadata":{"permalink":"/de/release/140","source":"@site/i18n/de/docusaurus-plugin-content-blog/140.mdx","title":"v1.4.0","description":"\xdcberwachungsfunktionen wurden hinzugef\xfcgt.","date":"2024-07-19T00:00:00.000Z","formattedDate":"19. Juli 2024","tags":[],"readingTime":0.355,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.4.0","last_update":"2024-07-19T00:00:00.000Z","date":"2024-07-19T00:00:00.000Z"},"prevItem":{"title":"v1.4.1","permalink":"/de/release/141"},"nextItem":{"title":"v1.3.1","permalink":"/de/release/131"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### \xdcberwachungsfunktionen wurden hinzugef\xfcgt.\\n\\n#### Unterst\xfctzte Sprachen f\xfcr den Service wurden erweitert.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Metrik\xfcberwachung der bereitgestellten Ressourcen hinzugef\xfcgt\\n    - Unterst\xfctzte CSP: Azure, AWS, Ncloud\\n2. Japanisch wird unterst\xfctzt.\\n\\n</div>\\n<br/>\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"changed\\">\\n    Update\\n</div>\\n\\n1. UI-Updates\\n    - Das detaillierte UI der Validierungspr\xfcfung wurde aktualisiert.\\n    - Das detaillierte UI der Bereitstellungshistorie wurde aktualisiert.\\n\\n</div>"},{"id":"/131","metadata":{"permalink":"/de/release/131","source":"@site/i18n/de/docusaurus-plugin-content-blog/131.mdx","title":"v1.3.1","description":"AWS Shared Account-Zertifikate werden unterst\xfctzt.","date":"2024-06-28T00:00:00.000Z","formattedDate":"28. Juni 2024","tags":[],"readingTime":0.395,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.3.1","last_update":"2024-06-28T00:00:00.000Z","date":"2024-06-28T00:00:00.000Z"},"prevItem":{"title":"v1.4.0","permalink":"/de/release/140"},"nextItem":{"title":"v1.3.0","permalink":"/de/release/130"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### AWS Shared Account-Zertifikate werden unterst\xfctzt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. AWS Shared Account-Unterst\xfctzung\\n    - Bei der Registrierung von AWS-Zertifikaten k\xf6nnen Sie zwischen dem Besitzkonto und dem Shared Account w\xe4hlen.\\n    - Bei Auswahl des Shared Accounts kann ein Session Token eingegeben werden.\\n\\n</div>\\n<br/>\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"fixed\\">\\n    Fixed\\n</div>\\n\\n1. Infrastruktur laden\\n    - Fehler beim Laden einiger AWS-Ressourcen wurden behoben.\\n    - Die Lade-Logik wurde \xfcberarbeitet.\\n\\n</div>"},{"id":"/130","metadata":{"permalink":"/de/release/130","source":"@site/i18n/de/docusaurus-plugin-content-blog/130.mdx","title":"v1.3.0","description":"CSP wurde hinzugef\xfcgt.","date":"2024-06-18T00:00:00.000Z","formattedDate":"18. Juni 2024","tags":[],"readingTime":0.505,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.3.0","last_update":"2024-06-18T00:00:00.000Z","date":"2024-06-18T00:00:00.000Z"},"prevItem":{"title":"v1.3.1","permalink":"/de/release/131"},"nextItem":{"title":"v1.2.0","permalink":"/de/release/120"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### CSP wurde hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. NHN Cloud-Dienst bereitgestellt\\n    - NHN Cloud wird unterst\xfctzt.\\n    - Es werden eingeschr\xe4nkte Funktionen f\xfcr Diagramme, Versionsverwaltung, Schwachstellenanalyse und Bereitstellungsmanagement angeboten.\\n\\n</div>\\n<br/>\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"fixed\\">\\n    Fixed\\n</div>\\n\\n1. Exportieren\\n    - Der Export nach der Bereitstellung wurde ge\xe4ndert, sodass nun auch ein Export vor der Bereitstellung m\xf6glich ist.\\n2. Ressourcen\\n    - Ncloud : Bei der \xc4nderung des Namens der Network Interface wird die Priorit\xe4t auf dem Server nicht mehr ge\xe4ndert.\\n3. Schwachstellenanalyse\\n    - Die Compliance-Mapping-Elemente der Schwachstellenanalyse wurden \xfcberarbeitet.\\n\\n</div>"},{"id":"/120","metadata":{"permalink":"/de/release/120","source":"@site/i18n/de/docusaurus-plugin-content-blog/120.mdx","title":"v1.2.0","description":"Funktionen wurden aktualisiert.","date":"2024-06-01T00:00:00.000Z","formattedDate":"1. Juni 2024","tags":[],"readingTime":0.305,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.2.0","last_update":"2024-06-01T00:00:00.000Z","date":"2024-06-01T00:00:00.000Z"},"prevItem":{"title":"v1.3.0","permalink":"/de/release/130"},"nextItem":{"title":"v1.1.0","permalink":"/de/release/110"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Funktionen wurden aktualisiert.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Schwachstellenanalyse Compliance-Mapping\\n    - Bei der Schwachstellenanalyse werden ISO 27001, ISMS-P, CSAP und CSP-Sicherheitsbewertungs-Kontrollpunkte angezeigt.\\n    - Die Geschwindigkeit der Schwachstellenanalyse wurde verbessert.\\n2. Kostenberechnung mit Traffic\\n    - Neben den Betriebskosten k\xf6nnen Sie den Traffic pro Ressource eingeben und die Kosten daf\xfcr berechnen.\\n\\n</div>"},{"id":"/110","metadata":{"permalink":"/de/release/110","source":"@site/i18n/de/docusaurus-plugin-content-blog/110.mdx","title":"v1.1.0","description":"Neue Funktionen wurden hinzugef\xfcgt.","date":"2024-05-01T00:00:00.000Z","formattedDate":"1. Mai 2024","tags":[],"readingTime":0.37,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.1.0","last_update":"2024-05-01T00:00:00.000Z","date":"2024-05-01T00:00:00.000Z"},"prevItem":{"title":"v1.2.0","permalink":"/de/release/120"},"nextItem":{"title":"v1.0.0","permalink":"/de/release/100"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Neue Funktionen wurden hinzugef\xfcgt.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"feature\\">\\n    Feature\\n</div>\\n\\n1. Infrastruktur laden\\n    - Bereits bereitgestellte Infrastruktur kann angezeigt und visualisiert werden.\\n    - Bestehende Infrastruktur kann in IaC umgewandelt und Statuswerte erstellt werden, die wiederverwendet werden k\xf6nnen.\\n2. Infrastruktur umwandeln\\n    - Das konfigurierte Infrastrukturdiagramm kann auf eine andere CSP (Cloud Service Provider) umgestellt werden.\\n    - Beim Umstellen werden die zugeordneten Ressourcen und Kosten verglichen.\\n\\n</div>"},{"id":"/100","metadata":{"permalink":"/de/release/100","source":"@site/i18n/de/docusaurus-plugin-content-blog/100.mdx","title":"v1.0.0","description":"Wir bieten Dienstleistungen f\xfcr Azure, AWS, Naver Cloud und Kubernetes an.","date":"2024-04-01T00:00:00.000Z","formattedDate":"1. April 2024","tags":[],"readingTime":0.75,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"v1.0.0","last_update":"2024-04-01T00:00:00.000Z","date":"2024-04-01T00:00:00.000Z"},"prevItem":{"title":"v1.1.0","permalink":"/de/release/110"}},"content":"import styles from \\"/src/scss/_markdown.module.scss\\"\\n\\n<hr />\\n\\n#### Wir bieten Dienstleistungen f\xfcr Azure, AWS, Naver Cloud und Kubernetes an.\\n\\n<div className={styles.releaseWrap} >\\n<div className={styles.tag} data-type=\\"new\\">\\n    New\\n</div>\\n<div>\\n\\n1. Cloud-Infrastruktur-Diagramm\\n    - Sie k\xf6nnen die Cloud-Infrastruktur per Drag & Drop entwerfen.\\n    - Fehler in der Konfiguration der Infrastruktur werden in Echtzeit angezeigt.\\n    - Das gezeichnete Infrastrukturdiagramm wird in IaC (Infrastructure as Code) umgewandelt.\\n2. Versionsverwaltung\\n    - Es wird eine Versionsspeicherfunktion f\xfcr die IaC-basierte Infrastruktur angeboten, mit der Sie zu einer bestimmten Version zur\xfcckkehren k\xf6nnen.\\n3. Kostenberechnung\\n    - Es werden monatliche, t\xe4gliche und st\xfcndliche Betriebskosten der gezeichneten Infrastruktur angezeigt (KRW, USD, JPY, EUR)\\n4. Schwachstellenanalyse\\n    - Eine Schwachstellenanalyse der gezeichneten Infrastruktur wird angeboten, zusammen mit einer Anleitung zur Behebung der Schwachstellen.\\n5. Bereitstellungsmanagement\\n    - Die gezeichnete Infrastruktur kann durch ein vorheriges Bereitstellungstest auf ihre G\xfcltigkeit \xfcberpr\xfcft werden, und sie kann mit den CSP-spezifischen Anmeldeinformationen verbunden werden, um die tats\xe4chliche Infrastruktur bereitzustellen.\\n\\n</div>\\n</div>"}]}')}}]);